import "gosvm/solana"

// Account order: pool, user signer, user X, vault X, vault Y, user Y,
// pool PDA authority, classic SPL Token program.
// Pool bytes: vaultX[32], vaultY[32], mintX[32], mintY[32], bump[1], swaps[8].
// Instruction bytes: amountIn[8], minOut[8], both little-endian.
func Process(c solana.Context) uint64 {
	if solana.Count(c) != 8 {
		return 101
	}
	state := solana.Data(c, 0)
	ix := solana.Instruction(c)
	if len(state) != 145 || len(ix) != 24 {
		return 102
	}
	if load64(state,0)!=13577703138238765809 || load64(ix,0)!=14449647541112719096 {return 102}
	if !same32(solana.Owner(c, 0), 0, solana.ProgramID(c), 0) || !solana.Writable(c, 0) || solana.Executable(c, 0) {
		return 103
	}
	if !solana.Signer(c, 1) || solana.Executable(c, 1) {
		return 104
	}
	if !solana.IsTokenProgram(c, 7) {
		return 105
	}
	for i := uint64(0); i < 8; i++ {
		for j := uint64(0); j < i; j++ {
			if same32(solana.Key(c, i), 0, solana.Key(c, j), 0) {
				return 106
			}
		}
	}
	if !same32(solana.Key(c, 3), 0, state, 8) || !same32(solana.Key(c, 4), 0, state, 40) {
		return 107
	}
	for i := uint64(2); i < 6; i++ {
		data := solana.Data(c, i)
		if len(data) != 165 || !solana.Writable(c, i) || solana.Executable(c, i) || !same32(solana.Owner(c, i), 0, solana.Key(c, 7), 0) {
			return 108
		}
		// Frozen accounts are left to SPL Token to reject. This also exercises a
		// second-CPI failure after the input transfer has already executed.
		if data[108] != 1 && data[108] != 2 {
			return 108
		}
		if load32(data, 109) != 0 {
			return 108
		} // Native/wrapped-SOL accounts excluded.
	}
	ux := solana.Data(c, 2)
	vx := solana.Data(c, 3)
	vy := solana.Data(c, 4)
	uy := solana.Data(c, 5)
	if same32(state, 72, state, 104) || !same32(ux, 0, state, 72) || !same32(vx, 0, state, 72) || !same32(vy, 0, state, 104) || !same32(uy, 0, state, 104) {
		return 109
	}
	if !same32(ux, 32, solana.Key(c, 1), 0) || !same32(uy, 32, solana.Key(c, 1), 0) || !same32(vx, 32, solana.Key(c, 6), 0) || !same32(vy, 32, solana.Key(c, 6), 0) {
		return 110
	}
	if !solana.IsPDA(c, 6, solana.Key(c, 0), state[136]) {
		return 111
	}
	x := load64(vx, 64)
	y := load64(vy, 64)
	amount := load64(ix, 8)
	if amount == 0 || x == 0 || y == 0 || amount > 18446744073709551615-x || load64(ux, 64) < amount {
		return 112
	}
	out := Quote(x, y, amount)
	if out == 0 || out < load64(ix, 16) || out > 18446744073709551615-load64(uy, 64) {
		return 113
	}
	n := load64(state, 137)
	if n == 18446744073709551615 {
		return 114
	}
	err := solana.Transfer(c, 7, 2, 3, 1, amount)
	if err != 0 {
		return err
	}
	err = solana.TransferSigned(c, 7, 4, 5, 6, out, solana.Key(c, 0), state[136])
	if err != 0 {
		return err
	}
	store64(state, 137, n+1)
	return 0
}

// Quote uses a 30bps fee rounded up in input units, retained in the input vault.
// Floor(y * net / (x + net)) uses a full 128-bit product without a native shim.
func Quote(x, y, amount uint64) uint64 {
	if x == 0 || y == 0 || amount == 0 || amount > 18446744073709551615-x {
		return 0
	}
	fee := (amount/10000)*30 + ((amount%10000)*30+9999)/10000
	net := amount - fee
	if net == 0 {
		return 0
	}
	return mulDiv(y, net, x+net)
}

// mulDiv is adapted from Go's math/bits Mul64 and Div64 (Go Authors, BSD-3-Clause;
// see THIRD_PARTY_NOTICES and third_party/Go-LICENSE). Its invalid-input sentinel
// is zero. Quote proves d>0 and quotient<=a, so it never reaches that case.
func mulDiv(a, b, d uint64) uint64 {
	const mask = 4294967295
	a0 := a & mask
	a1 := a >> 32
	b0 := b & mask
	b1 := b >> 32
	w0 := a0 * b0
	t := a1*b0 + (w0 >> 32)
	w1 := (t & mask) + a0*b1
	hi := a1*b1 + (t >> 32) + (w1 >> 32)
	lo := a * b
	if d == 0 || hi >= d {
		return 0
	}
	if hi == 0 {
		return lo / d
	}
	s := uint64(0)
	for d&9223372036854775808 == 0 {
		d = d << 1
		s++
	}
	const base = 4294967296
	d1 := d >> 32
	d0 := d & mask
	u32 := hi<<s | lo>>(64-s)
	u10 := lo << s
	u1 := u10 >> 32
	u0 := u10 & mask
	q1 := u32 / d1
	r := u32 - q1*d1
	for q1 >= base || q1*d0 > base*r+u1 {
		q1--
		r = r + d1
		if r >= base {
			break
		}
	}
	u21 := u32*base + u1 - q1*d
	q0 := u21 / d1
	r = u21 - q0*d1
	for q0 >= base || q0*d0 > base*r+u0 {
		q0--
		r = r + d1
		if r >= base {
			break
		}
	}
	return q1*base + q0
}

func same32(a []byte, ao uint64, b []byte, bo uint64) bool {
	if ao > uint64(len(a)) || uint64(len(a))-ao < 32 || bo > uint64(len(b)) || uint64(len(b))-bo < 32 {
		return false
	}
	for i := uint64(0); i < 32; i++ {
		if a[ao+i] != b[bo+i] {
			return false
		}
	}
	return true
}
func load64(data []byte, offset uint64) uint64 {
	var v uint64
	for i := uint64(0); i < 8; i++ {
		v = v | uint64(data[offset+i])<<(i*8)
	}
	return v
}
func load32(data []byte, offset uint64) uint64 {
	var v uint64
	for i := uint64(0); i < 4; i++ {
		v = v | uint64(data[offset+i])<<(i*8)
	}
	return v
}
func store64(data []byte, offset, value uint64) {
	for i := uint64(0); i < 8; i++ {
		data[offset+i] = byte(value >> (i * 8))
	}
}
